import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Using the API","description":"","frontmatter":{"title":"Using the API","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}`),a={name:`api/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to “Using the API”">​</a></h1><p>Every function of OEA is available through its REST API. The API is described by the contract <code>api/openapi.yaml</code> (OpenAPI 3.1); the pages of this chapter are generated from it and list only the operations implemented in this version.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to “Base URL”">​</a></h2><p>All operations are under <code>/api/v1</code> of the instance, for example <code>https://oea.example.org/api/v1/health</code>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h2><p>There is no anonymous access, except for a few public operations (health, setup, login). The web interface uses a <strong>session</strong>:</p><ol><li>Log in with <code>POST /auth/local/login</code> (local system admin account) or through an identity provider (<code>GET /auth/oidc/{providerId}/start</code>).</li><li>The session is the cookie <code>__Host-OEA_SESSION</code>. The login answer contains a <code>csrfToken</code>.</li><li>Send the token in the header <code>X-XSRF-TOKEN</code> with every changing request (<code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>).</li><li>End the session with <code>POST /auth/logout</code>.</li></ol><p><a href="./../administration/#log-in-for-administration-through-the-api">Log in for administration through the API</a> shows this with <code>curl</code>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Every operation states its required access:</p><ul><li><strong>public</strong>: no authentication</li><li><strong>any authenticated principal</strong>: any session; checks on the object itself may apply</li><li><strong>permission</strong>: the listed permissions are required; <em>one of the permissions</em> means that one of them suffices; <em>additionally … when …</em> names permissions that a particular request needs in addition</li></ul><p>Permissions come from roles, see <a href="./../administration/roles-and-permissions">Roles and permissions</a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p>Errors are answered as RFC 9457 problem details (<code>application/problem+json</code>). The field <code>type</code> names the problem as <code>urn:oea:problem:&lt;name&gt;</code>, for example <code>urn:oea:problem:validation-failed</code>; the reference lists the problem types per response.</p><ul><li><code>401</code>: not authenticated, or the session has ended</li><li><code>403</code>: a required permission is missing; the answer does not reveal which one</li><li><code>404</code>: the object does not exist – or you may not see it</li><li><code>413</code>: the request body is too large (see <a href="./../administration/operations#request-size-limits">Request size limits</a>)</li><li><code>422</code>: the request is well-formed but not valid</li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><p>The reference has one page per area of the API; open it in the sidebar.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};